function tournamentFromDb(row:any):Tournament{const p=row.platform_settings&&typeof row.platform_settings==='object'?row.platform_settings:{};const prize=row.prize_details;return {id:String(row.id),game:row.game_type||p.game||'تخته‌نرد',title:row.title||'',series:row.series_name||p.series||'',description:row.description||p.description||'',rules:row.rules||p.rules||'',capacity:row.capacity==null?(p.capacity||''):String(row.capacity),prize:typeof prize==='string'?prize:(prize?.text||prize?.display||p.prize||''),status:row.status==='draft'?'پیش‌نویس':row.registration_open?'در حال ثبت‌نام':'بسته',published:row.status!=='draft',date:p.date||(row.starts_at?String(row.starts_at).slice(0,10):''),participation:p.participation||'individual',teamSize:p.teamSize||'2',teamEntry:p.teamEntry||'preformed',progression:p.progression||'groups_knockout',seedingMetric:p.seedingMetric||'wins',seedingOrder:p.seedingOrder||'desc',tieBreakers:p.tieBreakers||'',qualifiersPerGroup:p.qualifiersPerGroup||'2',publicSeeding:p.publicSeeding!==false,publicDraw:p.publicDraw!==false,publicTables:p.publicTables!==false,publicBracket:p.publicBracket!==false};}
function tournamentToDb(t:Tournament,id:string,createdBy:string){const capacity=Number.parseInt(t.capacity,10);return {id,title:t.title.trim(),game_type:t.game||'تخته‌نرد',series_name:t.series||null,description:t.description||null,rules:t.rules||null,status:t.published?'published':'draft',registration_open:t.status==='در حال ثبت‌نام',capacity:Number.isFinite(capacity)&&capacity>0?capacity:null,prize_details:{text:t.prize||''},starts_at:t.date?new Date(t.date+'T12:00:00').toISOString():null,created_by:createdBy,updated_at:new Date().toISOString(),platform_settings:{date:t.date||'',participation:t.participation,teamSize:t.teamSize,teamEntry:t.teamEntry,progression:t.progression,seedingMetric:t.seedingMetric,seedingOrder:t.seedingOrder,tieBreakers:t.tieBreakers,qualifiersPerGroup:t.qualifiersPerGroup,publicSeeding:t.progression==='knockout_only'?false:t.publicSeeding,publicDraw:t.publicDraw,publicTables:t.publicTables,publicBracket:t.publicBracket}};}
function avatarStoragePath(value:string){
 if(!value)return '';
 if(value.startsWith('http://')||value.startsWith('https://')){
  const markers=['/storage/v1/object/public/avatars/','/storage/v1/object/sign/avatars/','/storage/v1/object/authenticated/avatars/'];
  for(const marker of markers){const i=value.indexOf(marker);if(i>=0){try{return decodeURIComponent(value.slice(i+marker.length).split('?')[0]);}catch{return value.slice(i+marker.length).split('?')[0]}}}
  return '';
 }
 return value;
}
async function getPrivateAvatarUrl(value:string,userId:string){
 if(!value||!supabase)return '';
 const path=avatarStoragePath(value);
 if(!path||!path.startsWith(userId+'/'))return '';
 const {data,error}=await supabase.storage.from('avatars').createSignedUrl(path,3600);
 return error||!data?.signedUrl?'':data.signedUrl;
}
